mapper.select:
SELECT r.GROUP_ROOM_NO, r.COMPANION_NO, r.ROOM_NAME,
/* 마지막 메시지 */ (SELECT MSG_CONTENT FROM GROUP_MESSAGE WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO ORDER BY GROUP_MSG_NO DESC FETCH FIRST 1 ROWS ONLY ) AS LAST_MESSAGE,
/* 마지막 메시지 시간 */ (SELECT TO_CHAR(SEND_TIME, 'YYYY-MM-DD HH24:MI') FROM GROUP_MESSAGE WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO ORDER BY GROUP_MSG_NO DESC FETCH FIRST 1 ROWS ONLY ) AS LAST_SEND_TIME,
/* 미읽음 메시지 수 */ (SELECT COUNT(*) FROM GROUP_MESSAGE gm WHERE gm.GROUP_ROOM_NO = r.GROUP_ROOM_NO AND gm.GROUP_MSG_NO > NVL( (SELECT LAST_READ_MSG FROM GROUP_MSG_READ WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO AND MEMBER_NO = #{memberNo}), 0) ) AS UNREAD_COUNT,
/* 멤버 수 */ (SELECT COUNT(*) FROM GROUP_CHAT_MEMBER WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO ) AS MEMBER_COUNT
FROM GROUP_CHAT_ROOM r WHERE EXISTS ( SELECT 1 FROM GROUP_CHAT_MEMBER WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO AND MEMBER_NO = #{memberNo} ) ORDER BY (SELECT SEND_TIME FROM GROUP_MESSAGE WHERE GROUP_ROOM_NO = r.GROUP_ROOM_NO ORDER BY GROUP_MSG_NO DESC FETCH FIRST 1 ROWS ONLY ) DESC NULLS LAST, r.CREATED_AT DESC

SELECT MEMBER_NO
FROM GROUP_CHAT_MEMBER
WHERE GROUP_ROOM_NO = #{groupRoomNo}
